(ns fastmath.signal.iir-test
  (:require [fastmath.signal.iir :as sut]
            [fastmath.signal.biquad :as biquad]
            [clojure.test :as t]
            [clojure.java.io :as io]
            [clojure.edn :as edn])
  (:import [uk.me.berndporr.iirj Cascade]
           [fastmath.vector Vec2]))

;; Reference values from scipy.signal (`butter`, `cheby1`, `cheby2`, `bessel(norm='phase')` with
;; `sosfilt` / `sosfreqz`, cookbook biquads with `lfilter`), generated by
;; `utils/fastmath/dev/generate_iir_reference.py` into `test/resources/signal/iir_reference.edn`.

(def ^:private reference
  (delay (edn/read-string (slurp (io/resource "signal/iir_reference.edn")))))

(defn- impulse-response
  [^Cascade iir n]
  (mapv (fn [i] (.filter iir (if (zero? i) 1.0 0.0))) (range n)))

(defn- max-diff
  [a b]
  (let [a (flatten (seq a)) b (flatten (seq b))]
    (if (= (count a) (count b))
      (reduce max 0.0 (map #(Math/abs (- (double %1) (double %2))) a b))
      Double/POSITIVE_INFINITY)))

(defn- design
  [{:keys [design] :as opts}]
  (case design
    :butterworth (sut/butterworth opts)
    :chebyshev (sut/chebyshev opts)
    :bessel (sut/bessel opts)))

(t/deftest designs-vs-scipy
  (doseq [{:keys [impulse response] :as e} (:designs @reference)
          direct-form [1 2]
          :let [opts (-> e (dissoc :impulse :response) (assoc :direct-form direct-form))
                label (str (:design e) " " (:kind e) " order " (:order e) " fs " (:fs e) " df " direct-form)]]
    (t/is (<= (max-diff impulse (impulse-response (design opts) 80)) 1.0e-13) (str label " impulse"))
    ;; iirj multiplies the section responses; measured maximum difference 1.2e-14
    (t/is (<= (max-diff response (map (fn [^Vec2 z] [(.x z) (.y z)]) (sut/response (design opts) 32))) 1.0e-12)
          (str label " response"))))

(t/deftest biquads-vs-lfilter
  (doseq [{:keys [kind impulse] :as e} (:biquads @reference)]
    (t/is (<= (max-diff impulse (impulse-response (sut/biquad (dissoc e :impulse)) 80)) 1.0e-14) (str kind))
    (t/is (<= (max-diff impulse (impulse-response (sut/biquad kind (dissoc e :impulse :kind)) 80)) 1.0e-14) (str kind " 2-arity"))))

(t/deftest biquad-Q-and-sos
  (let [by-bw (sut/biquad {:kind :bandpass :cutoff 1000.0 :fs 44100.0 :bandwidth 1.0})
        by-Q (sut/biquad {:kind :bandpass :cutoff 1000.0 :fs 44100.0
                          :Q (biquad/bandwidth->Q 1.0 1000.0 44100.0)})]
    (t/is (<= (max-diff (sut/sos-coeffs by-bw) (sut/sos-coeffs by-Q)) 1.0e-15) ":Q equals the converted bandwidth"))
  (let [iir (sut/butterworth {:order 5})
        copy (sut/sos (sut/sos-coeffs iir))]
    (t/is (= 3 (count (sut/sos-coeffs iir))) "order 5: three sections")
    (t/is (= (impulse-response iir 30) (impulse-response copy 30)) "sos round trip")
    (t/is (vector? (sut/response iir 8)))))

(t/deftest chebyshev-type-II-default
  ;; default stop band attenuation 40 dB, as cheby2(5, 40, 0.1)
  (let [iir (sut/chebyshev {:type :type-II})
        mags (map (fn [^Vec2 z] (Math/hypot (.x z) (.y z))) (sut/response iir 64))]
    (t/is (every? #(<= % (+ 0.01 1e-12)) (drop 10 mags)) "stop band below -40 dB")))

(t/deftest guards
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/butterworth {:kind :band})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/bessel {:kind :band})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/chebyshev {:kind :band})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/chebyshev {:kind :band :type :type-II})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/chebyshev {:type :type-III})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/butterworth {:direct-form 3})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/sos [[1 0 0 1 0 0]] 3)))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/butterworth {:order 0})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/biquad {:kind :shelf})))
  (doseq [design [sut/butterworth sut/bessel sut/chebyshev]
          cutoff [0.5 0.7 0.0 -0.1]]
    (t/is (thrown? clojure.lang.ExceptionInfo (design {:cutoff cutoff})) (str "cutoff " cutoff)))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/butterworth {:fs 0.0})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/butterworth {:kind :bandpass :cutoff 0.45 :bandwidth 0.2})) "upper edge above fs/2")
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/butterworth {:kind :bandstop :cutoff 0.05 :bandwidth 0.2})) "lower edge below 0")
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/butterworth {:kind :bandpass :bandwidth 0.0})))
  (t/is (some? (sut/butterworth {:cutoff 0.499})))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/sos [])))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/sos [[1 2 3]])))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/sos [[1 0 0 0 0 0]])) "a0 = 0"))

(t/deftest sos-coeffs-normalized
  ;; scipy.signal.butter(2, 0.2, output='sos')
  (t/is (<= (max-diff [[0.06745527388907194 0.13491054777814387 0.06745527388907194 1.0 -1.142980502539901 0.41280159809618866]]
                      (sut/sos-coeffs (sut/butterworth {:order 2 :cutoff 0.1})))
            1.0e-15))
  (t/is (every? #(== 1.0 (% 3)) (sut/sos-coeffs (sut/biquad {:kind :lowshelf :gain 6.0}))) "a0 = 1 also for cookbook sections"))
